private String[] dissect(String path) {
    char sep = File.separatorChar;
    path = path.replace('/', sep).replace('\\', sep);

    if (!isAbsolutePath(path)) {
        throw new BuildException(path + " is not an absolute path");
    }

    String root;
    String remaining;

    int colon = path.indexOf(':');
    if (colon > 0 && (ON_DOS || ON_NETWARE)) {
        root = path.substring(0, colon + 1);
        int next = colon + 1;
        if (path.charAt(next) == sep) {
            next++;
        }
        // remove consecutive separators
        StringBuilder sb = new StringBuilder();
        char prev = 0;
        for (int i = next; i < path.length(); i++) {
            char c = path.charAt(i);
            if (!(c == sep && prev == sep)) {
                sb.append(c);
            }
            prev = c;
        }
        remaining = sb.toString();
    } else if (path.length() > 1 && path.charAt(1) == sep) {
        int nextsep = path.indexOf(sep, 2);
        nextsep = path.indexOf(sep, nextsep + 1);
        root = (nextsep > 2) ? path.substring(0, nextsep + 1) : path;
        remaining = path.substring(root.length());
    } else {
        root = File.separator;
        remaining = path.substring(1);
    }

    return new String[]{root, remaining};
}
