    /**
     * Restores the heap property by moving the element at {@code index}
     * up the heap until it is no longer smaller than its parent.
     *
     * @param heap   the heap array
     * @param weight the weight array used for comparisons
     * @param index  the starting index of the element to bubble up
     */
    private static void bubbleUp(int[] heap, int[] weight, int index) {
        int tmp = heap[index];
        while (index > 1 && weight[tmp] < weight[heap[index >> 1]]) {
            heap[index] = heap[index >> 1];
            index >>= 1;
        }
        heap[index] = tmp;
    }

    /**
     * Restores the heap property by moving the element at {@code index}
     * down the heap until it is no longer larger than its children.
     *
     * @param heap   the heap array
     * @param weight the weight array used for comparisons
     * @param index  the starting index of the element to bubble down
     * @param heapSize the current size of the heap
     */
    private static void bubbleDown(int[] heap, int[] weight, int index, int heapSize) {
        int tmp = heap[index];
        while (true) {
            int child = index << 1;
            if (child > heapSize) {
                break;
            }
            if (child + 1 <= heapSize && weight[heap[child + 1]] < weight[heap[child]]) {
                child++;
            }
            if (weight[tmp] < weight[heap[child]]) {
                break;
            }
            heap[index] = heap[child];
            index = child;
        }
        heap[index] = tmp;
    }
}

