private static int heapifyDown(int[] heap, int nHeap, int[] weight) {
    int zz = 1;
    int tmp = heap[1];
    while (true) {
        int yy = zz << 1;
        if (yy > nHeap) break;
        if ((yy < nHeap) && (weight[heap[yy + 1]] < weight[heap[yy]])) yy++;
        if (weight[tmp] < weight[heap[yy]]) break;
        heap[zz] = heap[yy];
        zz = yy;
    }
    heap[zz] = tmp;
    return nHeap;
}

private static int heapifyUp(int[] heap, int nHeap, int[] weight) {
