private void processResource(Resource r, HashMap<File, List<String>> filesByBasedir,
        HashMap<File, List<String>> dirsByBasedir,
        HashSet<File> baseDirs) throws BuildException {
    if (!r.isExists()) {
        handleMissingResource(r);
        return;
    }
    File baseDir = getBaseDir(r);
    String name = getName(r);
    FileProvider fp = r.as(FileProvider.class);
    if (r.isDirectory() || fp != null) {
        add(baseDir, name, r.isDirectory() ? dirsByBasedir : filesByBasedir);
        baseDirs.add(baseDir);
    } else {
        pendingNonFileResources.add(r);
    }
}

