        }
        if (diagrams.size() > 0) {
            /* Use the first diagram. */
            return diagrams.get(0);
        }
        if (models.size() > 0) {
            /* If there was no diagram at all,
             * then use the (first) UML model. */
            return models.iterator().next();
        }
        return null;
    }

