static class ReceiverParams {
    final ExtendedBlock block;
    final StorageType storageType;
    final DataInputStream in;
    final String inAddr;
    final String myAddr;
    final BlockConstructionStage stage;
    final long newGs;
    final long minBytesRcvd;
    final long maxBytesRcvd;
    final String clientname;
    final DatanodeInfo srcDataNode;
    final DataNode datanode;
    final DataChecksum requestedChecksum;
    final CachingStrategy cachingStrategy;
    final boolean allowLazyPersist;
    final boolean pinning;

    private ReceiverParams(Builder b) {
        this.block = b.block;
        this.storageType = b.storageType;
        this.in = b.in;
        this.inAddr = b.inAddr;
        this.myAddr = b.myAddr;
        this.stage = b.stage;
        this.newGs = b.newGs;
        this.minBytesRcvd = b.minBytesRcvd;
        this.maxBytesRcvd = b.maxBytesRcvd;
        this.clientname = b.clientname;
        this.srcDataNode = b.srcDataNode;
        this.datanode = b.datanode;
        this.requestedChecksum = b.requestedChecksum;
        this.cachingStrategy = b.cachingStrategy;
        this.allowLazyPersist = b.allowLazyPersist;
        this.pinning = b.pinning;
    }

    static class Builder {
        private ExtendedBlock block;
        private StorageType storageType;
        private DataInputStream in;
        private String inAddr;
        private String myAddr;
        private BlockConstructionStage stage;
        private long newGs;
        private long minBytesRcvd;
        private long maxBytesRcvd;
        private String clientname;
        private DatanodeInfo srcDataNode;
        private DataNode datanode;
        private DataChecksum requestedChecksum;
        private CachingStrategy cachingStrategy;
        private boolean allowLazyPersist;
        private boolean pinning;

        Builder block(ExtendedBlock block) { this.block = block; return this; }
        Builder storageType(StorageType storageType) { this.storageType = storageType; return this; }
        Builder in(DataInputStream in) { this.in = in; return this; }
        Builder inAddr(String inAddr) { this.inAddr = inAddr; return this; }
        Builder myAddr(String myAddr) { this.myAddr = myAddr; return this; }
        Builder stage(BlockConstructionStage stage) { this.stage = stage; return this; }
        Builder newGs(long newGs) { this.newGs = newGs; return this; }
        Builder minBytesRcvd(long minBytesRcvd) { this.minBytesRcvd = minBytesRcvd; return this; }
        Builder maxBytesRcvd(long maxBytesRcvd) { this.maxBytesRcvd = maxBytesRcvd; return this; }
