Implementation:

public BlockReceiver(ReceiverParams params) throws IOException {
    try {
        this.block = params.block;
        this.in = params.in;
        this.inAddr = params.inAddr;
        this.myAddr = params.myAddr;
        this.srcDataNode = params.srcDataNode;
        this.datanode = params.datanode;
        this.clientname = params.clientname;
        this.isDatanode = params.clientname.length() == 0;
        this.isClient = !this.isDatanode;
        this.restartBudget = params.datanode.getDnConf().restartReplicaExpiry;
        this.datanodeSlowLogThresholdMs = params.datanode.getDnConf().datanodeSlowIoWarningThresholdMs;
        this.responseInterval = (long) (params.datanode.getDnConf().socketTimeout * 0.5);
        this.stage = params.stage;
        this.isTransfer = params.stage == BlockConstructionStage.TRANSFER_RBW
                || params.stage == BlockConstructionStage.TRANSFER_FINALIZED;
        this.pinning = params.pinning;
        if (LOG.isDebugEnabled()) {
            LOG.debug(getClass().getSimpleName() + ": " + block
                    + "\n  isClient  =" + isClient + ", clientname=" + clientname
                    + "\n  isDatanode=" + isDatanode + ", srcDataNode=" + srcDataNode
                    + "\n  inAddr=" + inAddr + ", myAddr=" + myAddr
                    + "\n  cachingStrategy = " + params.cachingStrategy
                    + "\n  pinning=" + pinning
                    );
        }
        // Open local disk out
        if (isDatanode) {
            replicaHandler = params.datanode.data.createTemporary(params.storageType, block);
        } else {
            switch (params.stage) {
                case PIPELINE_SETUP_CREATE:
                    replicaHandler = params.datanode.data.createRbw(params.storageType, block, params.allowLazyPersist);
                    params.datanode.notifyNamenodeReceivingBlock(
                            block, replicaHandler.getReplica().getStorageUuid());
                    break;
                case PIPELINE_SETUP_STREAMING_RECOVERY:
                    replicaHandler = params.datanode.data.recoverRbw(
                            block, params.newGs, params.minBytesRcvd, params.maxBytesRcvd);
                    block.setGenerationStamp(params.newGs);
                    break;
                case PIPELINE_SETUP_APPEND:
                    replicaHandler = params.datanode.data.append(block, params.newGs, params.minBytesRcvd);
                    block.setGenerationStamp(params.newGs);
                    params.datanode.notifyNamenodeReceivingBlock(
                            block, replicaHandler.getReplica().getStorageUuid());
                    break;
                case PIPELINE_SETUP_APPEND_RECOVERY:
                    replicaHandler = params.datanode.data.recoverAppend(block, params.newGs, params.minBytesRcvd);
                    block.setGenerationStamp(params.newGs);
                    params.datanode.notifyNamenodeReceivingBlock(
                            block, replicaHandler.getReplica().getStorageUuid());
                    break;
                case TRANSFER_RBW:
                case TRANSFER_FINALIZED:
                    replicaHandler =
                            params.datanode.data.createTemporary(params.storageType, block);
                    break;
                default: throw new IOException("Unsupported stage " + params.stage + 
                        " while receiving block " + block + " from " + inAddr);
            }
        }
        replicaInfo = replicaHandler.getReplica();
        this.dropCacheBehindWrites = (params.cachingStrategy.getDropBehind() == null) ?
                params.datanode.getDnConf().dropCacheBehindWrites :
                params.cachingStrategy.getDropBehind();
        this.syncBehindWrites = params.datanode.getDnConf().syncBehindWrites;
        this.syncBehindWritesInBackground = params.datanode.getDnConf().
                syncBehindWritesInBackground;
        final boolean isCreate = isDatanode || isTransfer 
                || params.stage == BlockConstructionStage.PIPELINE_SETUP_CREATE;
        streams = replicaInfo.createStreams(isCreate, params.requestedChecksum);
        assert streams != null : "null streams!";
        this.clientChecksum = params.requestedChecksum;
        this.diskChecksum = streams.getChecksum();
        this.needsChecksumTranslation = !clientChecksum.equals(diskChecksum);
        this.bytesPerChecksum = diskChecksum.getBytesPerChecksum();
        this.checksumSize = diskChecksum.getChecksumSize();
        this.out = streams.getDataOut();
        if (out instanceof FileOutputStream) {
            this.outFd = ((FileOutputStream)out).getFD();
        } else {
            LOG.warn("Could not get file descriptor for outputstream of class " +
                    out.getClass());
        }
        this.checksumOut = new DataOutputStream(new BufferedOutputStream(
                streams.getChecksumOut(), HdfsConstants.SMALL_BUFFER_SIZE));
        if (isCreate) {
            BlockMetadataHeader.writeHeader(checksumOut, diskChecksum);
        }
    } catch (ReplicaAlreadyExistsException bae) {
        throw bae;
    } catch (ReplicaNotFoundException bne) {
        throw bne;
    } catch(IOException ioe) {
        IOUtils.closeStream(this);
        cleanupBlock();
        IOException cause = DatanodeUtil.getCauseIfDiskError(ioe);
        DataNode.LOG.warn("IOException in BlockReceiver constructor. Cause is ",
                cause);
        if (cause != null) {
            ioe = cause;
            datanode.checkDiskErrorAsync();
        }
        throw ioe;
    }
}

