  private GetApplicationsRequest buildGetApplicationsRequest(
      String count, String startedBegin, String startedEnd,
      String finishBegin, String finishEnd,
      Set<String> applicationTypes, Set<String> applicationTags,
      String queueQuery, String userQuery,
      String stateQuery, Set<String> statesQuery) {
    GetApplicationsRequest request = GetApplicationsRequest.newInstance();

    if (count != null && !count.isEmpty()) {
      long countNum = parseLongParam(count, "limit", true);
      request.setLimit(countNum);
    }

    if (startedBegin != null || startedEnd != null) {
      long sBegin = parseLongParam(startedBegin, "startedTimeBegin", false);
      long sEnd = parseLongParam(startedEnd, "startedTimeEnd", false);
      if (sBegin > sEnd) {
        throw new BadRequestException(
            "startedTimeEnd must be greater than startTimeBegin");
      }
      request.setStartRange(sBegin, sEnd);
    }

    if (finishBegin != null || finishEnd != null) {
      long fBegin = parseLongParam(finishBegin, "finishedTimeBegin", false);
      long fEnd = parseLongParam(finishEnd, "finishedTimeEnd", false);
      if (fBegin > fEnd) {
        throw new BadRequestException(
            "finishTimeEnd must be greater than finishTimeBegin");
      }
      request.setFinishRange(fBegin, fEnd);
    }

    Set<String> appTypes = parseQueries(applicationTypes, false);
    if (!appTypes.isEmpty()) {
      request.setApplicationTypes(appTypes);
    }

    Set<String> appTags = parseQueries(applicationTags, false);
    if (!appTags.isEmpty()) {
      request.setApplicationTags(appTags);
    }

    Set<String> appStates = parseQueries(statesQuery, true);
    if (stateQuery != null && !stateQuery.isEmpty()) {
      appStates.add(stateQuery);
    }
    if (!appStates.isEmpty()) {
      request.setApplicationStates(appStates);
    }

    if (queueQuery != null && !queueQuery.isEmpty()) {
      validateQueueExists(queueQuery);
      request.setQueues(new HashSet<String>(1) {{ add(queueQuery); }});
    }

    if (userQuery != null && !userQuery.isEmpty()) {
      request.setUsers(new HashSet<String>(1) {{ add(userQuery); }});
    }

    return request;
  }

  private void validateQueueExists(String queueQuery) {
    ResourceScheduler rs = rm.getResourceScheduler();
    if (rs instanceof CapacityScheduler) {
      CapacityScheduler cs = (CapacityScheduler) rs;
      try {
        cs.getQueueInfo(queueQuery, false, false);
      } catch (IOException e) {
        throw new BadRequestException(e.getMessage());
      }
    }
  }

  private List<ApplicationReport> fetchApplicationReports(
      GetApplicationsRequest request) {
    try {
      return rm.getClientRMService()
          .getApplications(request, false).getApplicationList();
    } catch (YarnException e) {
      LOG.error("Unable to retrieve apps from ClientRMService", e);
      throw new YarnRuntimeException(
          "Unable to retrieve apps from ClientRMService", e);
    }
  }

  private AppsInfo processAppReports(List<ApplicationReport> appReports,
      HttpServletRequest hsr) {
    ConcurrentMap<ApplicationId, RMApp> apps =
        rm.getRMContext().getRMApps();
    AppsInfo allApps = new AppsInfo();
    for (ApplicationReport report : appReports) {
      RMApp rmapp = apps.get(report.getApplicationId());
      if (rmapp == null) {
        continue;
      }
      if (finalStatusFilter(report, rmapp)) {
        continue;
      }
      AppInfo app = new AppInfo(rm, rmapp,
          hasAccess(rmapp, hsr), WebAppUtils.getHttpSchemePrefix(conf));
      allApps.add(app);
    }
    return allApps;
  }

  private boolean finalStatusFilter(ApplicationReport report, RMApp rmapp) {
    String finalStatusQuery = report.getFinalApplicationStatus().toString();
    if (finalStatusQuery != null && !finalStatusQuery.isEmpty()) {
      FinalApplicationStatus.valueOf(finalStatusQuery);
      if (!rmapp.getFinalApplicationStatus().toString()
          .equalsIgnoreCase(finalStatusQuery)) {
        return true;
      }
    }
    return false;
  }

  @GET
